package org.joml; public class Vector3d implements Vector3dc { public double x,y,z; public Vector3d(){} public Vector3d(Vector3dc v){this(v.x(),v.y(),v.z());} public Vector3d(double x,double y,double z){this.x=x;this.y=y;this.z=z;} public double x(){return x;} public double y(){return y;} public double z(){return z;} public double length(){return Math.sqrt(x*x+y*y+z*z);} public boolean isFinite(){return Double.isFinite(x)&&Double.isFinite(y)&&Double.isFinite(z);} public Vector3d mul(double d){x*=d;y*=d;z*=d;return this;} public String toString(){return "("+x+","+y+","+z+")";} }
